With notation as in Example \ref{example-decompose-P1}
\begin{enumerate}
\item
the motive $(X, c_0, 0)$ is isomorphic to the motive
$\mathbf{1} = (\Spec(k), 1, 0)$.
\item
the motive $(X, c_2, 0)$ is isomorphic to the motive
$\mathbf{1}(-1) = (\Spec(k), 1, -1)$.
\end{enumerate}

In Situation \ref{situation-regular-model} the symmetric bilinear form
(\ref{equation-form}) has the following properties
\begin{enumerate}
\item $(C_i \cdot C_j) \geq 0$ if $i \not = j$ with equality if and only
if $C_i \cap C_j = \emptyset$,
\item $(\sum m_i C_i \cdot C_j) = 0$,
\item there is no nonempty proper subset $I \subset \{1, \ldots, n\}$
such that $(C_i \cdot C_j) = 0$ for $i \in I$, $j \not \in I$.
\item $(\sum a_i C_i \cdot \sum a_i C_i) \leq 0$ with equality if and
only if there exists a $q \in \mathbf{Q}$ such that $a_i = qm_i$
for $i = 1, \ldots, n$,
\end{enumerate}

In Situation \ref{situation-free-at-generic-points}.
\begin{enumerate}
\item The functor $H_p$ satisfies the sheaf property for the fpqc topology.
\item If $\mathcal{F}$ is of finite presentation, then functor $H_p$ is
limit preserving.
\end{enumerate}

The property of morphisms of germs of schemes
\begin{align*}
& \mathcal{P}((X, x) \to (S, s)) = \\
& \text{the local ring }
\mathcal{O}_{X_s, x}
\text{ of the fibre is Noetherian and Gorenstein}
\end{align*}
is \'etale local on the source-and-target (Descent, Definition
\ref{descent-definition-local-source-target-at-point}).

Let $X$ be a scheme.
\begin{enumerate}
\item If $D \subset X$ is an effective Cartier divisor, then
the canonical section $1_D$ of $\mathcal{O}_X(D)$ is regular.
\item Conversely, if $s$ is a regular section of the invertible
sheaf $\mathcal{L}$, then there exists a unique effective
Cartier divisor $D = Z(s) \subset X$ and a unique isomorphism
$\mathcal{O}_X(D) \to \mathcal{L}$ which maps $1_D$ to $s$.
\end{enumerate}
The constructions
$D \mapsto (\mathcal{O}_X(D), 1_D)$ and $(\mathcal{L}, s) \mapsto Z(s)$
give mutually inverse maps
$$
\left\{
\begin{matrix}
\text{effective Cartier divisors on }X
\end{matrix}
\right\}
\leftrightarrow
\left\{
\begin{matrix}
\text{isomorphism classes of pairs }(\mathcal{L}, s)\\
\text{consisting of an invertible }
\mathcal{O}_X\text{-module}\\
\mathcal{L}\text{ and a regular global section }s
\end{matrix}
\right\}
$$

There exist an open substack
$\Curvesstack^{Gorenstein, 1} \subset \Curvesstack$ such that
\begin{enumerate}
\item given a family of curves $X \to S$ the following are equivalent
\begin{enumerate}
\item the classifying morphism $S \to \Curvesstack$ factors
through $\Curvesstack^{Gorenstein, 1}$,
\item the morphism $X \to S$ is Gorenstein and has
relative dimension $1$ (Morphisms of Spaces, Definition
\ref{spaces-morphisms-definition-relative-dimension}),
\end{enumerate}
\item given a scheme $X$ proper over a field $k$ with $\dim(X) \leq 1$
the following are equivalent
\begin{enumerate}
\item the classifying morphism $\Spec(k) \to \Curvesstack$ factors
through $\Curvesstack^{Gorenstein, 1}$,
\item $X$ is Gorenstein and $X$ is equidimensional of
dimension $1$.
\end{enumerate}
\end{enumerate}

Given any glueing data of locally ringed spaces there
exists a locally ringed space $X$ and open subspaces
$U_i \subset X$ together with isomorphisms
$\varphi_i : X_i \to U_i$ of locally ringed spaces such that
\begin{enumerate}
\item $X=\bigcup_{i\in I} U_i$,
\item $\varphi_i(U_{ij}) = U_i \cap U_j$, and
\item $\varphi_{ij} =
\varphi_j^{-1}|_{U_i \cap U_j} \circ \varphi_i|_{U_{ij}}$.
\end{enumerate}
The locally ringed space $X$ is characterized by the following
mapping properties: Given a locally ringed space $Y$ we have
\begin{eqnarray*}
\Mor(X, Y) & = & \{ (f_i)_{i\in I} \mid
f_i : X_i \to Y, \ f_j \circ \varphi_{ij} = f_i|_{U_{ij}}\} \\
f & \mapsto & (f|_{U_i} \circ \varphi_i)_{i \in I} \\
\Mor(Y, X) & = &
\left\{
\begin{matrix}
\text{open covering }Y = \bigcup\nolimits_{i \in I} V_i\text{ and }
(g_i : V_i \to X_i)_{i \in I}
\text{ such that}\\
g_i^{-1}(U_{ij}) = V_i \cap V_j
\text{ and }
g_j|_{V_i \cap V_j} = \varphi_{ij} \circ g_i|_{V_i \cap V_j}
\end{matrix}
\right\} \\
g & \mapsto &
V_i = g^{-1}(U_i), \ g_i = \varphi_i^{-1} \circ g|_{V_i}
\end{eqnarray*}

In Algebraic and Formal Geometry, Situation
\ref{algebraization-situation-bootstrap}
we have $H^s_\mathfrak a(M) = \lim H^s_\mathfrak a(M/I^nM)$.

Properties (A), (B), (C), (D), and (E) of
More on Algebra, Section \ref{more-algebra-section-properties-formal-fibres}
hold for $P(k \to R) =$``$R$ is a Gorenstein ring''.

Assume that $\mathcal{C}$ is a site,
and $U$ is an object of $\mathcal{C}$ whose associated representable
presheaf is a sheaf. Constructions A and B above define
mutually inverse (!) functors of $2$-categories
$$
\left\{
\begin{matrix}
2\text{-category of}\\
\text{stacks over }\mathcal{C}/U
\end{matrix}
\right\}
\leftrightarrow
\left\{
\begin{matrix}
2\text{-category of pairs }(\mathcal{T}, p)
\text{ consisting} \\
\text{of a stack }\mathcal{T}\text{ over }\mathcal{C}\text{ and a morphism} \\
p : \mathcal{T} \to \mathcal{C}/U\text{ of stacks over }\mathcal{C}
\end{matrix}
\right\}
$$

